INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('78f04225-0188-4a5f-9641-566f2ca54937', 'b2b2b2b2-3030-4000-8000-000000000002', 18, 'Dia 18 — Gratidão', 'Semana 3: Reconstruir', '{"pch": "Transformaste o meu pranto em dan\u00e7a\u2026 A gratid\u00e3o muda o foco da dor para a gra\u00e7a.", "verse": "Sl 30,11", "lectio": "Leia Sl 30. De lamento a louvor.", "practice": "Escreva 5 coisas boas que existem por causa de algo dif\u00edcil.", "question": "O que de bom nasceu de algo que te machucou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;